# phase/Student_view/miniquiz.py
"""Mini-quiz generated by the RAG agent right after a student completes a lesson."""
import datetime

import streamlit as st

from utils import api as backend

LETTERS = ["A", "B", "C", "D"]


def _back_to_lessons():
    st.session_state.current_page = "Lessons"
    st.session_state.selected_lesson = None
    st.session_state.start_lesson = False
    st.rerun()


def show_page():
    ctx = st.session_state.get("mini_quiz_ctx") or {}
    items = st.session_state.get("generated_quiz") or []
    user = st.session_state.get("user") or {}

    st.title(f"🧠 Mini Quiz: {ctx.get('lesson_title', 'Lesson')}")

    summary = st.session_state.get("lesson_summary")
    if summary:
        with st.expander("📌 Quick summary from FinBuddy", expanded=True):
            st.markdown(summary)

    if not items:
        st.info("No quiz questions were generated for this lesson yet.")
        if st.button("⬅ Back to Lessons"):
            _back_to_lessons()
        return

    result = st.session_state.get("mini_quiz_result")

    # ---------------- answering ----------------
    if result is None:
        with st.form("mini_quiz_form"):
            answers = []
            for i, it in enumerate(items):
                st.markdown(f"**Q{i + 1}. {it['question']}**")
                labels = [f"{LETTERS[j]}. {opt}" for j, opt in enumerate(it["options"][:4])]
                choice = st.radio("Choose one", labels, index=None, key=f"mq_{i}", label_visibility="collapsed")
                answers.append(choice[0] if choice else "")
            submitted = st.form_submit_button("Submit answers", type="primary")

        if submitted:
            if any(a == "" for a in answers):
                st.warning("Answer every question first 🙂")
                return
            try:
                with st.spinner("Checking your answers..."):
                    score, total = backend.grade_quiz(
                        user["user_id"], ctx.get("lesson_id"), ctx.get("level_slug", "beginner"),
                        items, answers, ctx.get("assignment_id"),
                    )
                    nxt = backend.next_step(
                        user["user_id"], ctx.get("lesson_id"), ctx.get("level_slug", "beginner"),
                        items, answers, ctx.get("assignment_id"),
                    )
            except Exception as e:
                st.error(f"Could not grade the quiz: {e}")
                return
            st.session_state.mini_quiz_result = {"score": score, "total": total, "answers": answers, "next": nxt}
            st.rerun()
        return

    # ---------------- results ----------------
    score, total = result["score"], result["total"]
    st.markdown(f"### 🏆 You scored {score}/{total}  (+{score * 10} XP)")
    for i, (it, ans) in enumerate(zip(items, result["answers"])):
        key = it["answer_key"]
        opts = it["options"]
        right = opts[LETTERS.index(key)] if key in LETTERS[: len(opts)] else key
        if ans == key:
            st.markdown(f"✅ **Q{i + 1}. {it['question']}** — {right}")
        else:
            mine = opts[LETTERS.index(ans)] if ans in LETTERS[: len(opts)] else ans
            st.markdown(f"❌ **Q{i + 1}. {it['question']}**  \nYou picked: {mine}  \nCorrect: {right}")
            if it.get("explanation"):
                st.caption(it["explanation"])

    nxt = result.get("next") or {}
    if nxt.get("route") == "celebrate":
        st.balloons()
        st.success(nxt.get("message", "Perfect score!"))
        if st.button("🎮 Play Money Match"):
            st.session_state.current_page = "Game"
            st.session_state.current_game = nxt.get("game_slug", "money_match")
            st.rerun()
    elif nxt.get("feedback"):
        st.info("💬 FinBuddy says:")
        st.markdown(nxt["feedback"])

    c1, c2, c3 = st.columns(3)
    if c1.button("🔁 Try again"):
        st.session_state.mini_quiz_result = None
        st.rerun()
    if c2.button("💬 Ask the tutor"):
        st.session_state.messages = st.session_state.get("messages") or []
        st.session_state.messages.append({
            "id": str(datetime.datetime.now().timestamp()),
            "text": f"Can you help me understand the lesson '{ctx.get('lesson_title', '')}' better?",
            "sender": "user",
            "timestamp": datetime.datetime.now(),
        })
        st.session_state.chat_lesson_id = ctx.get("lesson_id")
        st.session_state.is_typing = True
        st.session_state.current_page = "Chatbot"
        st.rerun()
    if c3.button("⬅ Back to Lessons"):
        _back_to_lessons()
